-- Paid inputs: never cleared or regenerated by replay.
CREATE TABLE embedding_vectors (
    id TEXT PRIMARY KEY,
    record_kind TEXT NOT NULL,
    record_id TEXT NOT NULL,
    field TEXT NOT NULL,
    content_hash TEXT NOT NULL,
    model_id TEXT NOT NULL,
    task_prefix TEXT NOT NULL CHECK(task_prefix IN ('retrieval-document', 'retrieval-query', 'similarity')),
    dims INTEGER NOT NULL CHECK(dims > 0),
    vector BLOB NOT NULL CHECK(typeof(vector) = 'blob' AND length(vector) = 2 * dims),
    created_at TEXT NOT NULL,
    UNIQUE(record_kind, record_id, field, model_id, task_prefix, content_hash)
);
CREATE INDEX embedding_vectors_model ON embedding_vectors(model_id, record_kind);
CREATE TRIGGER embedding_vectors_dimensions_insert
BEFORE INSERT ON embedding_vectors
WHEN EXISTS (SELECT 1 FROM embedding_vectors WHERE model_id = NEW.model_id AND dims != NEW.dims)
BEGIN
    SELECT RAISE(ABORT, 'embedding model dimension mismatch');
END;
CREATE TRIGGER embedding_vectors_dimensions_update
BEFORE UPDATE ON embedding_vectors
WHEN EXISTS (SELECT 1 FROM embedding_vectors WHERE model_id = NEW.model_id AND dims != NEW.dims AND id != OLD.id)
BEGIN
    SELECT RAISE(ABORT, 'embedding model dimension mismatch');
END;

CREATE TABLE judgment_ledger (
    id TEXT PRIMARY KEY,
    created_at TEXT NOT NULL,
    supersedes_id TEXT REFERENCES judgment_ledger(id),
    task TEXT NOT NULL,
    left_kind TEXT NOT NULL,
    left_id TEXT NOT NULL,
    right_kind TEXT,
    right_id TEXT,
    judge TEXT NOT NULL CHECK(judge IN ('llm', 'verifier', 'owner', 'diagnoser', 'learner_card', 'exact_key')),
    judge_model TEXT,
    prompt_version TEXT,
    input_hash TEXT NOT NULL,
    verdict TEXT NOT NULL,
    score REAL,
    rationale TEXT NOT NULL,
    CHECK((right_kind IS NULL) = (right_id IS NULL)),
    CHECK(supersedes_id IS NULL OR supersedes_id != id)
);
CREATE INDEX judgment_ledger_question ON judgment_ledger(task, left_kind, left_id, right_kind, right_id);
CREATE TRIGGER judgment_ledger_no_update
BEFORE UPDATE ON judgment_ledger
BEGIN
    SELECT RAISE(ABORT, 'judgment_ledger is append-only');
END;
CREATE TRIGGER judgment_ledger_no_delete
BEFORE DELETE ON judgment_ledger
BEGIN
    SELECT RAISE(ABORT, 'judgment_ledger is append-only');
END;
-- Also reject replacement even when SQLite recursive triggers are disabled.
CREATE TRIGGER judgment_ledger_validate_insert
BEFORE INSERT ON judgment_ledger
BEGIN
    SELECT RAISE(ABORT, 'judgment_ledger is append-only')
      WHERE EXISTS (SELECT 1 FROM judgment_ledger WHERE id = NEW.id);
    SELECT RAISE(ABORT, 'llm/diagnoser judgments require nonempty judge_model and prompt_version')
      WHERE NEW.judge IN ('llm', 'diagnoser')
        AND (COALESCE(NEW.judge_model, '') = '' OR COALESCE(NEW.prompt_version, '') = '');
    SELECT RAISE(ABORT, 'supersession must identify the same question')
      WHERE NEW.supersedes_id IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM judgment_ledger
          WHERE id = NEW.supersedes_id AND task = NEW.task
            AND left_kind = NEW.left_kind AND left_id = NEW.left_id
            AND right_kind IS NEW.right_kind AND right_id IS NEW.right_id
      );
END;
